@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const modals=document.querySelectorAll('.discipline-modal'),close=()=>modals.forEach(m=>m.hidden=true);document.querySelectorAll('.discipline-page [data-close]').forEach(b=>b.onclick=close);document.querySelector('[data-open-report]').onclick=()=>document.querySelector('#reportModal').hidden=false;document.querySelectorAll('[data-open-detail]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.openDetail).hidden=false);
const buildings={{ Js::from($buildings) }},rooms={{ Js::from($rooms) }},residents={{ Js::from($residents) }},cite=document.querySelector('#incidentCite'),building=document.querySelector('#incidentBuilding'),room=document.querySelector('#incidentRoom'),resident=document.querySelector('#incidentResident');const options=(el,data,key,label,placeholder)=>{el.replaceChildren(new Option(placeholder,''));data.forEach(x=>el.add(new Option(label(x),x[key])))};const loadResidents=()=>options(resident,residents.filter(x=>String(x.chambre_id)===room.value),'id',x=>`${x.name} — ${x.matricule||''}`,'Sélectionner');const loadRooms=()=>{options(room,rooms.filter(x=>String(x.batiment_id)===building.value),'id_chambre',x=>`Chambre ${x.numero_chambre}`,'Sélectionner');loadResidents()};const loadBuildings=()=>{options(building,buildings.filter(x=>String(x.cite_id)===cite.value),'id_batiment',x=>x.name,'Sélectionner');loadRooms()};cite.onchange=loadBuildings;building.onchange=loadRooms;room.onchange=loadResidents;loadBuildings();
const sanctionType=document.getElementById('sanctionType'),sanctionTarget=document.getElementById('sanctionTarget'),sanctionEnd=document.getElementById('sanctionEnd');
const updateSanction=()=>{
const deciding=document.getElementById('transitionAction').value==='decider',value=sanctionType.value;
document.getElementById('sanctionFields').hidden=!deciding;
sanctionType.disabled=!deciding;sanctionType.required=deciding;
sanctionTarget.disabled=!deciding||!value||value==='aucune';sanctionTarget.required=!sanctionTarget.disabled;
document.getElementById('sanctionTargetField').hidden=sanctionTarget.disabled;
sanctionEnd.disabled=!deciding||value!=='suspension';sanctionEnd.required=!sanctionEnd.disabled;
document.getElementById('sanctionEndField').hidden=sanctionEnd.disabled;
document.getElementById('sanctionEffect').textContent=value==='expulsion'?'Expulsion : nouvelles admissions et attributions bloquées, réservations annulées et sortie préparée. La place reste occupée jusqu’à l’état des lieux de sortie.':value==='suspension'?'Suspension immédiate : nouvelles admissions, attributions et confirmations bloquées jusqu’à la date indiquée incluse. Le séjour existant reste enregistré.':'La décision et son auteur sont conservés dans l’historique.';
};sanctionType.onchange=updateSanction;
const transitionConfig={transmettre:{title:'Transmettre au Service Sécurité',help:'Le dossier sera placé dans la file de traitement du Service Sécurité.',comment:'Note de transmission',required:false,icon:'fa-paper-plane',submit:'Transmettre'},prendre_en_charge:{title:'Prendre en charge le dossier',help:'Le rapport passera en cours d’analyse sous votre responsabilité.',comment:'Premières observations',required:false,icon:'fa-user-shield',submit:'Prendre en charge'},retourner:{title:'Retourner le rapport',help:'Le dossier sera renvoyé pour correction ou complément d’information.',comment:'Motif du retour *',required:true,icon:'fa-rotate-left',submit:'Retourner le dossier'},decider:{title:'Rendre une décision',help:'Formalisez la mesure disciplinaire retenue avant notification.',comment:'Motifs et observations *',required:true,icon:'fa-gavel',submit:'Enregistrer la décision'},cloturer:{title:'Clôturer le dossier',help:'Le traitement sera marqué comme terminé. L’historique restera consultable.',comment:'Note de clôture',required:false,icon:'fa-lock',submit:'Clôturer'}};
document.querySelectorAll('.transition[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action,config=transitionConfig[action];document.querySelector('#transitionForm').action=b.dataset.url;document.querySelector('#transitionAction').value=action;sanctionType.value='';sanctionTarget.value='';sanctionEnd.value='';updateSanction();document.querySelector('#transitionTitle').textContent=config.title;document.querySelector('#transitionHelp').textContent=config.help;document.querySelector('#transitionReport').textContent=b.dataset.report||'—';document.querySelector('#transitionResident').textContent=b.dataset.resident||'—';document.querySelector('#transitionNature').textContent=b.dataset.nature||'—';document.querySelector('#transitionIcon').innerHTML=`<i class="fa-solid ${config.icon}"></i>`;document.querySelector('#commentLabel').textContent=config.comment;const comment=document.querySelector('#commentField textarea');comment.required=config.required;const decision=document.querySelector('#decisionField');decision.hidden=action!=='decider';decision.querySelector('textarea').required=action==='decider';document.querySelector('#transitionSubmit').innerHTML=`<i class="fa-solid fa-check"></i> ${config.submit}`;document.querySelector('#transitionModal').hidden=false});@if($errors->any()) document.querySelector('#reportModal').hidden=false; @endif});
</script>@endpush
